CREATE TABLE banks (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL);
CREATE TABLE accounts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, token VARCHAR(128) NOT NULL UNIQUE, bank_id BIGINT REFERENCES banks(id), opened_at TIMESTAMP WITH TIME ZONE NOT NULL, segment VARCHAR(40) NOT NULL, kyc_tier VARCHAR(30) NOT NULL, is_external BOOLEAN NOT NULL DEFAULT FALSE, display_name VARCHAR(120), masked_account VARCHAR(30), balance_paise BIGINT NOT NULL DEFAULT 0, monthly_turnover_paise BIGINT NOT NULL DEFAULT 0);
CREATE TABLE transactions (txn_id VARCHAR(100) PRIMARY KEY, reference_token VARCHAR(128), src_token VARCHAR(128) NOT NULL, dst_token VARCHAR(128) NOT NULL, initiated_at TIMESTAMP WITH TIME ZONE NOT NULL, posted_at TIMESTAMP WITH TIME ZONE NOT NULL, amount_paise BIGINT NOT NULL CHECK(amount_paise > 0), rail VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL, source_hash VARCHAR(64));
CREATE INDEX idx_txn_src_time ON transactions(src_token, posted_at); CREATE INDEX idx_txn_dst_time ON transactions(dst_token, posted_at); CREATE INDEX idx_txn_ref ON transactions(reference_token);
CREATE TABLE endpoints (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, token VARCHAR(128) NOT NULL UNIQUE, kind VARCHAR(20) NOT NULL);
CREATE TABLE account_endpoint (account_token VARCHAR(128) NOT NULL, endpoint_token VARCHAR(128) NOT NULL, PRIMARY KEY(account_token, endpoint_token));
CREATE TABLE complaints (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, complaint_ref VARCHAR(100) NOT NULL UNIQUE, victim_name VARCHAR(120) NOT NULL, victim_token VARCHAR(128), amount_paise BIGINT NOT NULL, incident_at TIMESTAMP WITH TIME ZONE NOT NULL, payer_bank VARCHAR(80), reference_token VARCHAR(128), status VARCHAR(30) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE cases (case_id VARCHAR(40) PRIMARY KEY, complaint_id BIGINT REFERENCES complaints(id), status VARCHAR(30) NOT NULL, officer VARCHAR(120), created_at TIMESTAMP WITH TIME ZONE NOT NULL, confirmed_txn_id VARCHAR(100));
CREATE TABLE case_links (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, case_id VARCHAR(40) REFERENCES cases(case_id), txn_id VARCHAR(100) REFERENCES transactions(txn_id), score DOUBLE PRECISION NOT NULL, basis VARCHAR(500), confirmed_by VARCHAR(120), confirmed_at TIMESTAMP WITH TIME ZONE, UNIQUE(case_id, txn_id));
CREATE TABLE trail_edges (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, case_id VARCHAR(40) NOT NULL, txn_id VARCHAR(100), src_token VARCHAR(128) NOT NULL, dst_token VARCHAR(128) NOT NULL, amount_paise BIGINT NOT NULL, tainted_paise BIGINT NOT NULL, event_at TIMESTAMP WITH TIME ZONE, evidence_type VARCHAR(20) NOT NULL, hop INTEGER NOT NULL);
CREATE TABLE account_scores (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, case_id VARCHAR(40) NOT NULL, account_token VARCHAR(128) NOT NULL, pre_complaint_score DOUBLE PRECISION NOT NULL, priority_score DOUBLE PRECISION NOT NULL, role VARCHAR(40) NOT NULL, recommendation VARCHAR(100) NOT NULL, reasons CLOB, tainted_held_paise BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP WITH TIME ZONE NOT NULL, UNIQUE(case_id, account_token));
CREATE TABLE reviews (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, case_id VARCHAR(40) NOT NULL, account_token VARCHAR(128) NOT NULL, reviewer VARCHAR(120) NOT NULL, decision VARCHAR(20) NOT NULL, reason CLOB NOT NULL, lien_paise BIGINT NOT NULL, reviewed_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE audit_log (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, event_json CLOB NOT NULL, previous_hash VARCHAR(64) NOT NULL, event_hash VARCHAR(64) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE report_manifests (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, case_id VARCHAR(40) NOT NULL, file_name VARCHAR(255) NOT NULL, file_hash VARCHAR(64) NOT NULL, manifest_json CLOB NOT NULL, signature CLOB NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE token_vault (token VARCHAR(128) PRIMARY KEY, encrypted_value CLOB NOT NULL, nonce VARCHAR(80) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE ground_truth (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, case_id VARCHAR(40), account_token VARCHAR(128), expected_role VARCHAR(40), expected_positive BOOLEAN NOT NULL);
CREATE TABLE source_imports (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, source_name VARCHAR(255), source_hash VARCHAR(64) NOT NULL, purpose VARCHAR(500) NOT NULL, authority_reference VARCHAR(200) NOT NULL, imported_by VARCHAR(120) NOT NULL, imported_at TIMESTAMP WITH TIME ZONE NOT NULL);
